+const circuitBreakerDefaults = {
+  threshold: 5,
+  cooldown: 30_000,
+  halfOpenMaxRequests: 1,
+  failureStatusCodes: [408, 409, 425, 429, 500, 502, 503, 504],
+};
+
+type CircuitState = {
+  status: "closed" | "open" | "half-open";
+  failures: number;
+  openedAt: number;
+  halfOpenRequests: number;
+};
+
+type CircuitOptions = typeof circuitBreakerDefaults;
+
+type CircuitRequest = {
+  options: CircuitOptions;
+  origin?: string;
+  state?: CircuitState;
+  admitted: boolean;
+};
+
+const circuitBreakerStateKey = Symbol("ofetch.circuitBreakerState");
+const circuitRequestKey = Symbol("ofetch.circuitRequest");
+
+type InternalCreateFetchOptions = CreateFetchOptions & {
+  [circuitBreakerStateKey]?: Map<string, CircuitState>;
+};
+
+type InternalFetchOptions = FetchOptions & {
+  [circuitRequestKey]?: CircuitRequest;
+};
+
+function resolveCircuitOptions(value: FetchOptions["circuitBreaker"]) {
+  if (!value) {
+    return;
+  }
+  const options = value === true ? {} : value;
