+import { afterEach, describe, expect, it, vi } from "vitest";
+import { createFetch } from "../src/index.ts";
+
+const circuitBreaker = {
+  threshold: 1,
+  cooldown: 100,
+  halfOpenMaxRequests: 1,
+  failureStatusCodes: [500],
+};
+
+describe("circuit breaker", () => {
+  afterEach(() => {
+    vi.useRealTimers();
+  });
+
+  it("opens per origin and shares state with derived clients", async () => {
+    const fetch = vi.fn<typeof globalThis.fetch>().mockResolvedValue(
+      new Response("failure", { status: 500 })
+    );
+    const client = createFetch({ fetch });
+    const derived = client.create({});
+
+    await expect(
+      client.raw("https://example.test/one", { circuitBreaker, retry: false })
+    ).rejects.toThrow("500");
+    await expect(
+      derived.raw("https://example.test/two", { circuitBreaker })
+    ).rejects.toThrow("Circuit breaker is open");
+    expect(fetch).toHaveBeenCalledOnce();
+  });
+
+  it("uses the effective URL after request hooks and baseURL resolution", async () => {
+    const fetch = vi.fn<typeof globalThis.fetch>().mockResolvedValue(
+      new Response("failure", { status: 500 })
+    );
+    const client = createFetch({ fetch });
+
+    await expect(
+      client.raw("/one", {
+        baseURL: "https://first.test",
+        circuitBreaker,
+        retry: false,
+        onRequest: ({ request }) => {
+          request = "https://rewritten.test/one";
+        },
+      })
+    ).rejects.toThrow();
+    await expect(
+      client.raw("https://rewritten.test/two", { circuitBreaker })
+    ).rejects.toThrow("Circuit breaker is open");
+    expect(fetch).toHaveBeenCalledOnce();
+  });
+
+  it("allows one deterministic half-open probe and closes on success", async () => {
+    vi.useFakeTimers();
+    vi.setSystemTime(0);
+    const fetch = vi
+      .fn<typeof globalThis.fetch>()
+      .mockResolvedValueOnce(new Response("failure", { status: 500 }))
+      .mockResolvedValueOnce(new Response("ok", { status: 200 }));
+    const client = createFetch({ fetch });
+
+    await expect(
+      client.raw("https://example.test/one", { circuitBreaker, retry: false })
+    ).rejects.toThrow();
+    vi.setSystemTime(100);
+    await expect(
+      client.raw("https://example.test/two", { circuitBreaker })
+    ).resolves.toMatchObject({ status: 200 });
+    await expect(
+      client.raw("https://example.test/three", { circuitBreaker })
+    ).resolves.toMatchObject({ status: 200 });
+  });
+
+  it("rejects excess half-open probes without calling fetch", async () => {
+    vi.useFakeTimers();
+    vi.setSystemTime(0);
+    let resolveProbe!: (response: Response) => void;
+    const fetch = vi
+      .fn<typeof globalThis.fetch>()
+      .mockResolvedValueOnce(new Response("failure", { status: 500 }))
+      .mockImplementationOnce(
+        () => new Promise<Response>((resolve) => (resolveProbe = resolve))
+      );
+    const client = createFetch({ fetch });
+
+    await expect(
+      client.raw("https://example.test/one", { circuitBreaker, retry: false })
+    ).rejects.toThrow();
+    vi.setSystemTime(100);
+    const probe = client.raw("https://example.test/two", { circuitBreaker });
+    await expect(
+      client.raw("https://example.test/three", { circuitBreaker })
+    ).rejects.toThrow("Circuit breaker is open");
+    expect(fetch).toHaveBeenCalledTimes(2);
+    resolveProbe(new Response("ok", { status: 200 }));
+    await expect(probe).resolves.toMatchObject({ status: 200 });
+  });
+
+  it("does not reset failures for a rejected non-listed status", async () => {
+    const fetch = vi
+      .fn<typeof globalThis.fetch>()
+      .mockResolvedValueOnce(new Response("failure", { status: 500 }))
+      .mockResolvedValueOnce(new Response("missing", { status: 404 }))
+      .mockResolvedValueOnce(new Response("failure", { status: 500 }));
+    const client = createFetch({ fetch });
+    const options = { ...circuitBreaker, threshold: 2 };
+
+    await expect(
+      client.raw("https://example.test/one", { circuitBreaker: options, retry: false })
+    ).rejects.toThrow();
+    await expect(
+      client.raw("https://example.test/two", { circuitBreaker: options, retry: false })
+    ).rejects.toThrow("404");
+    await expect(
+      client.raw("https://example.test/three", { circuitBreaker: options, retry: false })
+    ).rejects.toThrow();
+    await expect(
+      client.raw("https://example.test/four", { circuitBreaker: options })
+    ).rejects.toThrow("Circuit breaker is open");
+  });
+});
