const circuitRequestKey = Symbol("ofetch.circuitRequest");

type InternalCreateFetchOptions = CreateFetchOptions & {
  [circuitBreakerStateKey]?: Map<string, CircuitState>;
};

type InternalFetchOptions = FetchOptions & {
  [circuitRequestKey]?: CircuitRequest;
};

function resolveCircuitOptions(value: FetchOptions["circuitBreaker"]) {
  if (!value) {
    return;
  }
  const options = value === true ? {} : value;
  return {
    threshold: Math.max(
      1,
      options.threshold ?? circuitBreakerDefaults.threshold
    ),
    cooldown: Math.max(0, options.cooldown ?? circuitBreakerDefaults.cooldown),
    halfOpenMaxRequests: Math.max(
      1,
      options.halfOpenMaxRequests ?? circuitBreakerDefaults.halfOpenMaxRequests
    ),
    failureStatusCodes:
      options.failureStatusCodes ?? circuitBreakerDefaults.failureStatusCodes,
  };
}

function getRequestOrigin(request: FetchRequest): string | undefined {
  const url =
